create table public.chat_users (user_id uuid primary key references auth.users(id) on delete cascade, username text not null check(username ~ '^[A-Za-z0-9]{1,12}$'), changed_at timestamptz not null default now(), muted_until timestamptz, chat_banned boolean not null default false, created_at timestamptz not null default now());
create unique index chat_username_unique on public.chat_users(lower(username));
create table public.chat_messages (id bigint generated always as identity primary key, user_id uuid not null references public.chat_users(user_id), body text not null default '' check(char_length(body)<=4000), reply_to bigint references public.chat_messages(id), file_path text, file_name text, file_type text, file_size bigint check(file_size between 1 and 20971520), created_at timestamptz not null default now(), deleted boolean not null default false, check(length(trim(body))>0 or file_path is not null));
create index chat_messages_created_idx on public.chat_messages(created_at desc,id desc);
create table public.chat_reactions (message_id bigint references public.chat_messages(id) on delete cascade, user_id uuid references public.chat_users(user_id) on delete cascade, emoji text not null check(emoji in ('👍','❤️','😂','🔥','😮')), created_at timestamptz default now(),primary key(message_id,user_id,emoji));
alter table public.chat_users enable row level security;
alter table public.chat_messages enable row level security;
alter table public.chat_reactions enable row level security;
revoke all on public.chat_users,public.chat_messages,public.chat_reactions from anon,authenticated;
insert into storage.buckets(id,name,public,file_size_limit) values ('chat-files','chat-files',false,20971520);
create or replace function public.chat_me() returns jsonb language plpgsql stable security definer set search_path='' as $$
declare u public.chat_users;begin if not lecture_private.session_allowed() then raise exception 'access_denied'; end if; select * into u from public.chat_users where user_id=auth.uid(); if not found then return null; end if;return jsonb_build_object('username',u.username,'changed_at',u.changed_at,'next_change',u.changed_at+interval '90 days','muted_until',u.muted_until,'chat_banned',u.chat_banned);end $$;
create or replace function public.chat_set_username(p_username text) returns jsonb language plpgsql security definer set search_path='' as $$
declare u public.chat_users;begin if not lecture_private.session_allowed() then raise exception 'access_denied'; end if; if p_username !~ '^[A-Za-z0-9]{1,12}$' then raise exception 'invalid_username';end if; select * into u from public.chat_users where user_id=auth.uid() for update; if found then if u.chat_banned or u.muted_until>now() then raise exception 'chat_restricted'; end if; if lower(u.username)=lower(p_username) then return public.chat_me();end if; if u.changed_at+interval '90 days'>now() then raise exception 'username_cooldown';end if;update public.chat_users set username=p_username,changed_at=now() where user_id=auth.uid();else insert into public.chat_users(user_id,username) values(auth.uid(),p_username);end if;return public.chat_me();exception when unique_violation then raise exception 'username_taken';end $$;
create or replace function public.chat_can_send() returns boolean language sql stable security definer set search_path='' as $$ select lecture_private.session_allowed() and exists(select 1 from public.chat_users where user_id=auth.uid() and not chat_banned and (muted_until is null or muted_until<=now())) $$;
create policy chat_storage_upload on storage.objects for insert to authenticated with check(bucket_id='chat-files' and (storage.foldername(name))[1]=auth.uid()::text and public.chat_can_send());
create policy chat_storage_read on storage.objects for select to authenticated using(bucket_id='chat-files' and lecture_private.session_allowed() and public.chat_me() is not null);
create policy chat_storage_delete_own on storage.objects for delete to authenticated using(bucket_id='chat-files' and (storage.foldername(name))[1]=auth.uid()::text);
create or replace function public.chat_send(p_body text,p_reply bigint default null,p_file_path text default null,p_file_name text default null,p_file_type text default null,p_file_size bigint default null) returns bigint language plpgsql security definer set search_path='' as $$
declare mid bigint;begin if not public.chat_can_send() then raise exception 'chat_restricted';end if; if char_length(coalesce(p_body,''))>4000 then raise exception 'message_too_long';end if;if p_reply is not null and not exists(select 1 from public.chat_messages where id=p_reply and not deleted) then raise exception 'reply_missing';end if;
if p_file_path is not null then if p_file_path not like auth.uid()::text||'/%' or p_file_size is null or p_file_size>20971520 or p_file_size<1 or not exists(select 1 from storage.objects where bucket_id='chat-files' and name=p_file_path and owner_id=auth.uid()::text and (metadata->>'size')::bigint=p_file_size) then raise exception 'invalid_attachment';end if;end if;
insert into public.chat_messages(user_id,body,reply_to,file_path,file_name,file_type,file_size) values(auth.uid(),trim(coalesce(p_body,'')),p_reply,p_file_path,left(p_file_name,180),left(p_file_type,100),p_file_size) returning id into mid;return mid;end $$;
create or replace function public.chat_list(p_before bigint default null,p_limit integer default 50) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare result jsonb;begin if not lecture_private.session_allowed() or not exists(select 1 from public.chat_users where user_id=auth.uid()) then raise exception 'access_denied';end if;
select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') into result from (select m.id,u.username,m.user_id=auth.uid() mine,m.body,m.created_at,m.deleted,m.file_path,m.file_name,m.file_type,m.file_size,m.reply_to,ru.username reply_username,left(r.body,160) reply_body,coalesce((select jsonb_agg(jsonb_build_object('emoji',r2.emoji,'count',r2.n,'mine',r2.mine)) from (select emoji,count(*) n,bool_or(user_id=auth.uid()) mine from public.chat_reactions where message_id=m.id group by emoji) r2),'[]'::jsonb) reactions from public.chat_messages m join public.chat_users u on u.user_id=m.user_id left join public.chat_messages r on r.id=m.reply_to left join public.chat_users ru on ru.user_id=r.user_id where not m.deleted and (p_before is null or m.id<p_before) order by m.id desc limit least(greatest(p_limit,1),100)) x;return result;end $$;
create or replace function public.chat_react(p_message bigint,p_emoji text) returns void language plpgsql security definer set search_path='' as $$ begin if not public.chat_can_send() then raise exception 'chat_restricted';end if;if p_emoji not in ('👍','❤️','😂','🔥','😮') then raise exception 'invalid_reaction';end if; if not exists(select 1 from public.chat_messages where id=p_message and not deleted) then raise exception 'message_missing';end if;delete from public.chat_reactions where message_id=p_message and user_id=auth.uid() and emoji=p_emoji;if not found then insert into public.chat_reactions(message_id,user_id,emoji) values(p_message,auth.uid(),p_emoji) on conflict do nothing;end if;end $$;
create or replace function public.chat_admin_users() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin if not lecture_private.is_admin() then raise exception 'access_denied';end if;return coalesce((select jsonb_agg(to_jsonb(x)) from (select u.user_id,u.username,u.muted_until,u.chat_banned,p.blocked site_blocked from public.chat_users u join public.profiles p on p.id=u.user_id order by u.created_at desc limit 200) x),'[]'::jsonb);end $$;
create or replace function public.chat_moderate(p_user uuid,p_action text,p_hours integer default null) returns void language plpgsql security definer set search_path='' as $$ begin if not lecture_private.is_admin() then raise exception 'access_denied';end if;if exists(select 1 from public.profiles where id=p_user and is_admin) then raise exception 'admin_protected';end if;if p_action='freeze' and p_hours between 1 and 8760 then update public.chat_users set muted_until=now()+make_interval(hours=>p_hours) where user_id=p_user;elsif p_action='unfreeze' then update public.chat_users set muted_until=null where user_id=p_user;elsif p_action='ban_chat' then update public.chat_users set chat_banned=true where user_id=p_user;elsif p_action='unban_chat' then update public.chat_users set chat_banned=false where user_id=p_user;elsif p_action='ban_site' then update public.profiles set blocked=true where id=p_user;update public.devices set blocked=true where owner_id=p_user;elsif p_action='unban_site' then update public.profiles set blocked=false where id=p_user;update public.devices set blocked=false where owner_id=p_user;else raise exception 'invalid_action';end if;end $$;
revoke all on function public.chat_me(),public.chat_set_username(text),public.chat_can_send(),public.chat_send(text,bigint,text,text,text,bigint),public.chat_list(bigint,integer),public.chat_react(bigint,text),public.chat_admin_users(),public.chat_moderate(uuid,text,integer) from public,anon;
grant execute on function public.chat_me(),public.chat_set_username(text),public.chat_can_send(),public.chat_send(text,bigint,text,text,text,bigint),public.chat_list(bigint,integer),public.chat_react(bigint,text),public.chat_admin_users(),public.chat_moderate(uuid,text,integer) to authenticated;
